'use strict';

function numberInSpanish(n){
 const small=['cero','uno','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez','once','doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte','veintiuno','veintidós','veintitrés','veinticuatro','veinticinco','veintiséis','veintisiete','veintiocho','veintinueve'];
 const apocope=s=>s.replace(/veintiuno$/,'veintiún').replace(/uno$/,'un');
 n=Math.floor(n);
 if(n<30)return small[n];
 if(n<100)return ['', '', '', 'treinta','cuarenta','cincuenta','sesenta','setenta','ochenta','noventa'][Math.floor(n/10)]+(n%10?' y '+small[n%10]:'');
 if(n===100)return 'cien';
 if(n<1000)return ['', 'ciento','doscientos','trescientos','cuatrocientos','quinientos','seiscientos','setecientos','ochocientos','novecientos'][Math.floor(n/100)]+(n%100?' '+numberInSpanish(n%100):'');
 if(n<1000000)return (n<2000?'mil':apocope(numberInSpanish(Math.floor(n/1000)))+' mil')+(n%1000?' '+numberInSpanish(n%1000):'');
 return (n<2000000?'un millón':apocope(numberInSpanish(Math.floor(n/1000000)))+' millones')+(n%1000000?' '+numberInSpanish(n%1000000):'');
}
function moneyInWords(value){
 const cents=Math.round(Math.abs(value)*100),whole=Math.floor(cents/100);
 const words=numberInSpanish(whole).replace(/veintiuno$/,'veintiún').replace(/uno$/,'un');
 return `${value<0?'MENOS ':''}${words.toLocaleUpperCase('es-SV')} ${String(cents%100).padStart(2,'0')}/100 DÓLARES DE LOS ESTADOS UNIDOS DE AMÉRICA`;
}
function letterHeader(){return `<header class="letter-header"><h2>COMPROBANTE DE LIQUIDACIÓN DE PRESTACIONES LABORALES</h2><p>República de El Salvador</p></header>`;}
function letterFooter(page,stamp){return `<footer class="letter-footer"><span>Generado el ${escapeHTML(stamp)} · Prototipo académico</span><span>${page} / 2</span></footer>`;}
function reportContent(){
 const a=exampleAmounts(),b=bonusEstimate(),c=monthlyContributions(),stamp=new Intl.DateTimeFormat('es-SV',{dateStyle:'short',timeStyle:'short',timeZone:'America/El_Salvador'}).format(new Date());
 const labels=[['Persona trabajadora',data.worker||'Sin indicar','Patrono',data.employer||'Sin indicar'],['Cargo desempeñado',data.role||'Sin indicar','Salario mensual',money(data.salary)],['Fecha de ingreso',dateLabel(data.start),'Fecha de terminación',dateLabel(data.end)],['Antigüedad reconocida',tenure()?.text||'Por completar','Causa de terminación',data.termination==='despido'?'Despido sin causa justificada':'Renuncia voluntaria']];
 const rows=[...a.rows].sort((x,y)=>{const order=v=>v.label.startsWith('Vacaciones')?0:v.label.startsWith('Aguinaldo')?1:v.label.startsWith('Indemnización')||v.label.startsWith('Prestación')?2:3;return order(x)-order(y);});
 const vac=data.vacation==='si'?`${data.vacationPortion==='semana'?'Solo una semana':data.vacationPortion==='completas'?'Completas':'Otro período'}: ${vacationDays()} días, del ${dateLabel(data.vacStart)} al ${dateLabel(data.vacEnd)}. Pendientes de ese período: ${vacationBalance().remaining}.`:'No se registraron vacaciones disfrutadas.';
 return `<article class="report-sheet model-letter"><section class="letter-page">${letterHeader()}<div class="letter-demo"><strong>DEMOSTRACIÓN.</strong> Contiene estimaciones y montos de ejemplo. El neto excluye ISR y usa ISSS/AFP mensuales de referencia; no acredita una liquidación definitiva ni un pago.</div><h3>I. Datos de las partes</h3><table class="letter-identity"><tbody>${labels.map(row=>`<tr><td>${row[0]}</td><td><strong>${escapeHTML(row[1])}</strong></td><td>${row[2]}</td><td><strong>${escapeHTML(row[3])}</strong></td></tr>`).join('')}</tbody></table><h3>II. Desglose de prestaciones liquidadas</h3><table class="letter-table"><thead><tr><th>Concepto</th><th>Base legal / referencia</th><th>Monto</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.label)}</td><td>${escapeHTML(r.base)}</td><td>${money(r.amount)}</td></tr>`).join('')}<tr class="letter-gross"><td colspan="2">TOTAL DEVENGADO (BRUTO)</td><td>${money(a.gross)}</td></tr></tbody></table><h3>III. Deducciones y neto ilustrativo</h3><p class="letter-note">Base mensual usada para la referencia ISSS/AFP: ${money(c.salary)}. La remuneración gravada y los conceptos exentos de esta liquidación requieren cálculo definitivo por concepto y mes.</p><table class="letter-table letter-deductions"><tbody><tr><td>Cotización ISSS (trabajador)</td><td>3% · tope mensual de $30</td><td>−${money(a.isss)}</td></tr><tr><td>Cotización AFP (trabajador)</td><td>7.25% · sin techo salarial</td><td>−${money(a.afp)}</td></tr><tr><td>Retención de ISR</td><td>Art. 37 Ley de ISR</td><td>Por calcular</td></tr><tr class="letter-gross"><td colspan="2">Deducciones de referencia (sin ISR)</td><td>−${money(a.isss+a.afp)}</td></tr><tr class="letter-net"><td colspan="2">NETO ILUSTRATIVO ANTES DE ISR</td><td>${money(a.net)}</td></tr></tbody></table><div class="letter-words"><span>Monto ilustrativo en letras</span><strong>${moneyInWords(a.net)}</strong></div>${letterFooter(1,stamp)}</section><section class="letter-page">${letterHeader()}<h3>IV. Declaración</h3><p class="letter-declaration">La persona trabajadora <strong>${escapeHTML(data.worker)||'________________________'}</strong> declara haber recibido el detalle de las prestaciones económicas, las deducciones y el monto neto presentados en este comprobante. En esta versión académica los importes son ilustrativos y requieren validación antes de utilizarse en una liquidación real. Este documento no declara que se haya recibido un pago.</p><div class="letter-signatures"><div><strong>Persona trabajadora</strong><p>Nombre: ______________________________</p><p>DUI: _________________________________</p><p>Fecha: _______________________________</p></div><div><strong>Patrono o representante legal</strong><p>Nombre: ______________________________</p><p>DUI: _________________________________</p><p>Fecha: _______________________________</p></div></div><div class="letter-warning"><strong>Advertencia legal</strong><p>Este documento es un comprobante informativo del cálculo de prestaciones y NO constituye el finiquito laboral. Conforme al art. 402 inciso 2 del Código de Trabajo, los documentos de renuncia, terminación por mutuo consentimiento o recibo de prestaciones por despido sin causa legal requieren las formalidades correspondientes para tener valor probatorio: hojas expedidas por la autoridad laboral competente, utilizadas dentro de los diez días siguientes a su expedición, o documento privado autenticado ante notario. Se recomienda asesoría legal antes de suscribir un finiquito.</p></div><div class="letter-answers"><h3>Datos utilizados en la demostración</h3><p><strong>Vacaciones:</strong> ${escapeHTML(vac)}</p><p><strong>Pago de vacaciones:</strong> ${data.vacation==='si'?({completo:'Completo recibido',parcial:'Parcial recibido',pendiente:'Pendiente',nose:'Por confirmar'}[data.vacationPayment]||'Por confirmar'):'No aplica al período registrado'}.</p><p><strong>Aguinaldo:</strong> ${b.label}. Estimación ${money(b.amount)}; recibido ${money(b.paid)}; pendiente ${money(b.pending)}.</p><p><strong>Horas extras:</strong> ${data.overtime?`${overtimeRows.length} registros; ${hours(overtimeEstimate().dayHours)} horas diurnas y ${hours(overtimeEstimate().nightHours)} nocturnas.`:'No.'}</p><p><strong>Asuetos pendientes:</strong> ${data.holiday?`${selectedHolidays().length} días seleccionados. ${selectedHolidays().slice(0,3).map(r=>`${escapeHTML(holidayName(r))} (${dateLabel(r.date)})`).join(', ')}${selectedHolidays().length>3?'; más '+(selectedHolidays().length-3)+' días registrados.':''}`:'No.'}</p><p><strong>Descansos semanales:</strong> ${data.rest?`${restRows.length} días registrados.`:'No.'}</p><p class="letter-note">Aguinaldo 2026: el pago puede adelantarse desde el 1 de octubre; la referencia para el proporcional se conserva al 12 de diciembre. ${b.recognizedEarly?'Se registró reconocimiento de pago completo anticipado por la empresa.':''}</p></div>${letterFooter(2,stamp)}</section></article>`;
}
